//! Provides the self-hosted Spass numeric core to the inference engine.

pub use spass_infer::bootstrap::core_stats;

// Generated by build.rs from the Spass core library. Function names
// follow the codegen mangler (`_spass_<name>_<arity>_<types>`); a
// rename on the Spass side is caught by the `bridge_*` tests below.
#[allow(
    dead_code,
    unused_imports,
    unused_mut,
    unused_parens,
    unused_variables,
    unused_assignments,
    non_snake_case,
    non_camel_case_types
)]
mod gen {
    include!(concat!(env!("OUT_DIR"), "/bootstrap_gen.rs"));
}

/// The Spass core implementation. Every method forwards to the
/// compiled `_spass_*` function; tuple returns are flattened into the
/// arrays the trait documents.
pub struct SpassCore;

impl spass_infer::bootstrap::NumericCore for SpassCore {
    fn state_count_nd(&self, span_n: f64, span_d: f64, step_n: f64, step_d: f64) -> f64 {
        gen::_spass_state_count_nd_4_f_f_f_f(span_n, span_d, step_n, step_d)
    }

    fn bit_width(&self, n: f64) -> i32 {
        gen::_spass_bit_width_1_f(n)
    }

    fn rat_add_nd(&self, an: f64, ad: f64, bn: f64, bd: f64) -> (f64, f64) {
        let r = gen::_spass_rat_add_nd_4_f_f_f_f(an, ad, bn, bd);
        (r._f0, r._f1)
    }

    fn gcd_step_nd(&self, an: f64, ad: f64, bn: f64, bd: f64) -> (f64, f64) {
        let r = gen::_spass_gcd_step_nd_4_f_f_f_f(an, ad, bn, bd);
        (r._f0, r._f1)
    }

    fn mul_corners_nd(&self, a: &[f64; 8]) -> [f64; 8] {
        let r = gen::_spass_mul_corners_nd_8_f_f_f_f_f_f_f_f(a[0], a[1], a[2], a[3], a[4], a[5], a[6], a[7]);
        [r._f0, r._f1, r._f2, r._f3, r._f4, r._f5, r._f6, r._f7]
    }
}

/// Install the Spass numeric core into the inference engine. Call once
/// at host startup (later calls are no-ops).
pub fn install() {
    spass_infer::bootstrap::install(&SpassCore);
}

#[cfg(test)]
mod tests {
    use super::*;
    use num_rational::Rational64;
    use spass_infer::Range;

    /// Serialises the stats-sensitive tests: `core_stats` counters are
    /// process-global and the fallback test deliberately increments the
    /// fallback count, which would race with the adopt test's delta
    /// assertions under cargo's default multi-threaded harness.
    static STATS_TEST_LOCK: std::sync::Mutex<()> = std::sync::Mutex::new(());

    fn r(min: i64, max: i64, step_num: i64, step_den: i64) -> Range {
        Range {
            min: Rational64::from_integer(min),
            max: Rational64::from_integer(max),
            step: Rational64::new(step_num, step_den),
        }
    }

    #[test]
    fn bridge_adopts_spass_results() {
        install();
        assert!(spass_infer::bootstrap::core_installed());

        // Stats are process-global; assert on deltas so the test is
        // order-independent. The delta readouts are NOT thread-safe
        // against the fallback test below (which deliberately bumps
        // the fallback counter), so the stats-sensitive tests take
        // this lock - cargo runs them concurrently by default.
        let _guard = STATS_TEST_LOCK.lock().unwrap();

        let (c0, f0) = core_stats();

        // state_count + bit_width through the bridge.
        let range = r(-5, 5, 1, 10); // 101 states -> 7 bits
        assert_eq!(range.state_count(), Some(101));
        assert_eq!(range.bit_width(), 7);

        // ADD/SUB through the bridge: gcd(0.1, 0.5) = 0.1.
        let a = r(0, 100, 1, 10);
        let b = r(0, 100, 1, 2);
        let c = spass_infer::infer_add_sub(&a, &b);
        assert_eq!(c.min, Rational64::from_integer(0));
        assert_eq!(c.max, Rational64::from_integer(200));
        assert_eq!(c.step, Rational64::new(1, 10));

        // MUL through the bridge: corners of [-5,5] x [-5,5].
        let m = spass_infer::infer_mul(&r(-5, 5, 1, 1), &r(-5, 5, 1, 1));
        assert_eq!(m.min, Rational64::from_integer(-25));
        assert_eq!(m.max, Rational64::from_integer(25));

        // The bridge must actually have been taken (not silent fallback).
        let (c1, f1) = core_stats();
        assert!(c1 > c0, "bridge never adopted a Spass result");
        assert_eq!(f1, f0, "unexpected fallbacks during adopt test");
    }

    #[test]
    fn bridge_falls_back_outside_exact_domain() {
        install();
        // A state count beyond 2^53 cannot cross the f64 bridge; the
        // Rust result must be used and counted as a fallback. 2^62 is
        // the `float` default domain's bound, so this is a realistic
        // shape.
        let _guard = STATS_TEST_LOCK.lock().unwrap();
        let (_, f0) = core_stats();
        let huge = Range {
            min: Rational64::from_integer(0),
            max: Rational64::from_integer(1i64 << 62),
            step: Rational64::new(1, 1),
        };
        assert!(huge.state_count().is_some()); // must not panic
        let (_, f1) = core_stats();
        assert!(f1 > f0, "expected at least one fallback");
    }

    #[test]
    fn bridge_handles_rational_steps() {
        install();
        // 1/10 steps are the common real-world case; the num/den pair
        // crosses exactly and gcd(0.1, 0.25) = 0.05.
        let a = r(0, 10, 1, 10);
        let b = r(0, 10, 1, 4);
        let c = spass_infer::infer_add_sub(&a, &b);
        assert_eq!(c.step, Rational64::new(1, 20));
        assert_eq!(c.max, Rational64::from_integer(20));
    }
}
